def binary_search(arr,target):
    left=0
    right=len(arr)-1
    while left<=right:
        mid=left+(right-left)//2
        if arr[mid]<target:
            left=mid+1
        elif arr[mid]>target:
            right=mid-1
        else:
            return mid
    return -1

def is_balanced(s):
    stack=[]
    for c in s:
        if c=='(':
            stack.append(c)
        elif c==')':
            if not stack:
                return False
            stack.pop()
    return len(stack)==0
